              <tr aria-hidden="true" style={{ height: rowWindow.bottomPad }} />
            )}
            {fillerCount > 0 && (
              <tr aria-hidden="true" data-filler-row>
                <td
                  colSpan={colCount}
                  style={{ blockSize: `calc(var(--_row-height) * ${fillerCount})`, padding: 0 }}
                />
              </tr>
            )}
          </tbody>
        </table>
      </div>
      {pagination && (
        <div className={styles['footer']}>
          {pagination.pageSizeOptions && (
            <label className={styles['pageSize']}>
              <span>Rows per page</span>
              <select
                value={pageSizeSignal.value}
                onChange={(event) => {
                  pageSizeSignal.value = Number(event.target.value)
                  pageSignal.value = 1
                }}
              >
                {pagination.pageSizeOptions.map((option) => (
                  <option key={option} value={option}>
                    {option}
                  </option>
                ))}
              </select>
            </label>
          )}
          <span className={styles['range']}>
            {rangeStart}–{rangeEnd} of {totalRows}
          </span>
          <div className={styles['pageButtons']}>
            <button
              type="button"
              className={styles['pageButton']}
              aria-label={l.previousPage}
              disabled={currentPage.value <= 1}
              onClick={() => {
                pageSignal.value = currentPage.value - 1
              }}
            >
              <span aria-hidden="true">‹</span>
            </button>
            <button
              type="button"
              className={styles['pageButton']}
              aria-label={l.nextPage}
              disabled={currentPage.value >= pageCount.value}
              onClick={() => {
                pageSignal.value = currentPage.value + 1
              }}
            >
              <span aria-hidden="true">›</span>
            </button>
          </div>
        </div>
      )}
    </div>
  )
}

/**
 * Substring search over rows that stays cheap while the user types.
 *
 * The naive filter — `String(cell).toLowerCase().includes(q)` per column per row on every
 * keystroke — is what a million-row table paid: ~500–850 ms of main-thread time per key
 * (measured), so the search box lagged a word behind the user. Two things fix it:
 *
 * 1. **One haystack per row.** `haystackOf` is expected to be cached by the caller (the
 *    table keys a `Map` on the row entry), so a key costs one `includes` per row, not one
 *    `String`/`toLowerCase` per cell.
 * 2. **Incremental narrowing.** A query that extends the previous one (`per` → `pers`) can
 *    only match a subset of the previous result, so it is filtered from that result rather
 *    than from every row. Typing gets cheaper with every character; only a shorter or
 *    different query — or a different base `rows` array — starts over.
 *
 * Order is preserved, which is what lets the table sort **once** and filter the sorted rows
 * per keystroke instead of re-sorting the filtered rows.
 */
export interface RowSearch<T> {
  /** The rows of `rows` whose haystack contains `query` (lower-cased, trimmed by the caller), in order. */
  filter(rows: readonly T[], query: string): readonly T[]
  /**
   * Build the haystacks of `rows[from, from + count)` ahead of any query, so the first
   * keystroke does not pay for the whole index (~1.5 s at a million rows). Returns the next
   * index to prime; the caller spreads calls over idle time.
   */
  prime(rows: readonly T[], from: number, count: number): number
}

/** Build a {@link RowSearch}; `haystackOf` yields the lower-cased searchable text of one row. */
export function createRowSearch<T>(haystackOf: (row: T) => string): RowSearch<T> {
  let lastRows: readonly T[] | undefined
  let lastQuery = ''
  let lastResult: readonly T[] = []

  return {
    filter(rows, query) {
      if (query === '') {
        lastRows = rows
        lastQuery = ''
        lastResult = rows
        return rows
      }
      const sameBase = rows === lastRows
      if (sameBase && query === lastQuery) return lastResult
      const narrowing = sameBase && lastQuery !== '' && query.startsWith(lastQuery)
      const candidates = narrowing ? lastResult : rows
      const out: T[] = []
      for (const row of candidates) if (haystackOf(row).includes(query)) out.push(row)
      lastRows = rows
      lastQuery = query
      lastResult = out
      return out
    },
    prime(rows, from, count) {
      const to = Math.min(rows.length, from + count)
      for (let i = from; i < to; i++) haystackOf(rows[i] as T)
      return to
    },
  }
}

/**
 * Stable client-side sort of rows by one column.
 *
 * The comparator-per-pair approach — `String(a).localeCompare(String(b))` inside
 * `Array.prototype.sort` — took **~4 s** to sort a million names (measured in Chromium):
 * `localeCompare` resolves a collator on every call, and the string conversion ran ~20
 * million times. What replaces it:
 *
 * - **Keys are extracted once per row**, not once per comparison.
 * - **Numbers compare by subtraction**; no collator is touched when every key is a number.
 * - **Strings are ranked, then the ranks are sorted.** The distinct values are collated once
 *   with a single `Intl.Collator` and given integer ranks, and the rows are then sorted by
 *   rank — a numeric sort. A status or city column with a few hundred distinct values sorts
 *   a million rows in the time it takes to sort a few hundred strings; a column of unique
 *   strings still pays one collation sort of its values, which is the floor.
 *
 * Ties break on original position, so the sort is stable regardless of engine.
 */
export function sortRows<T>(
  rows: readonly T[],
  keyOf: (row: T) => unknown,
  direction: 'asc' | 'desc',
): T[] {
  const n = rows.length
  if (n < 2) return [...rows]
  const ranks = new Float64Array(n)
  let allNumbers = true
  const keys: unknown[] = Array.from({ length: n })
  for (let i = 0; i < n; i++) {
    const k = keyOf(rows[i] as T)
    keys[i] = k
    if (typeof k !== 'number') allNumbers = false
  }

  const sign = direction === 'desc' ? -1 : 1
  // A plain array: a typed array sorts ~2x slower under a JS comparator (measured).
  const order = Array.from({ length: n }, (_, i) => i)
  const collect = (): T[] => order.map((i) => rows[i] as T)

  if (allNumbers) {
    for (let i = 0; i < n; i++) ranks[i] = keys[i] as number
  } else {
    const strings: string[] = Array.from({ length: n })
    for (let i = 0; i < n; i++) strings[i] = String(keys[i] ?? '')
    const compare = new Intl.Collator().compare
    if (mostlyDistinct(strings)) {
      // Ranking would only add a map over a million entries before the same collation
      // sort; compare the strings directly.
      order.sort((a, b) => {
        const r = compare(strings[a] as string, strings[b] as string)
        return r !== 0 ? sign * r : a - b
      })
      return collect()
    }
    // Rank the distinct strings by collation; a row's sort key is its string's rank.
    const rankOf = new Map<string, number>()
    for (let i = 0; i < n; i++) rankOf.set(strings[i] as string, 0)
    const distinct = [...rankOf.keys()].sort(compare)
    for (let r = 0; r < distinct.length; r++) rankOf.set(distinct[r] as string, r)
    for (let i = 0; i < n; i++) ranks[i] = rankOf.get(strings[i] as string) as number
  }

  order.sort((a, b) => {
    const r = (ranks[a] as number) - (ranks[b] as number)
    return r !== 0 ? sign * r : a - b
  })
  return collect()
}

/** Sampled cardinality: are the first couple of thousand values almost all different? */
function mostlyDistinct(strings: readonly string[]): boolean {
  const sample = Math.min(strings.length, 2048)
  const seen = new Set<string>()
  for (let i = 0; i < sample; i++) seen.add(strings[i] as string)
  return seen.size > sample * 0.9
}

/**
 * The arithmetic behind the virtualized row window, kept pure so the two things that
 * decide whether a million-row table works — *which* rows to render, and *where* to put
 * them — are unit-testable without a DOM.
 *
 * Positions are arithmetic on a fixed row height (the density presets size every row to
 * `--_row-height`), so scrolling never measures. The one twist is the **canvas cap**:
 * browsers clamp an element's height — Chromium at 33,554,432 px, Firefox at 17,895,697 px
 * — and a million 49 px rows is 49,000,000 px. Sized honestly, the scroller silently stops
 * at the cap and the last ~160k rows can never be scrolled to (measured: 1,000,000 rows,
 * bottom of the scrollbar, last rendered row 838,871). So the canvas is capped and, above
 * the cap, the scroll position is mapped onto the row space by ratio, exactly the way the
 * big grids do it. Below the cap the ratio is 1 and the layout is byte-identical to the
 * naive spacer layout.
 */

/**
 * Tallest canvas the scroller is allowed to be. Under every engine's clamp with room to
 * spare, and still ~1.3 s of continuous wheel-scrolling from top to bottom at a typical
 * 240 px per tick, so the scrollbar stays a usable control.
 */
export const MAX_CANVAS_PX = 12_000_000

export interface WindowInput {
  /** The scroller's current `scrollTop`, in canvas pixels. */
  scrollTop: number
  /** The scroller's `clientHeight`. */
  viewportHeight: number
  /** Height of one row, in px. Must be > 0. */
  rowHeight: number
  /** Total rows in the collection being windowed. */
  count: number
  /** Rows rendered beyond each edge of the viewport. */
  overscan: number
  /** Canvas cap; exposed for tests. */
  maxCanvas?: number
}

export interface RowWindow {
  /** First rendered row (inclusive). */
  start: number
  /** Last rendered row (exclusive). */
  end: number
  /** Height of the spacer above the first rendered row, in canvas px. */
  topPad: number
  /** Height of the spacer below the last rendered row, in canvas px. */
  bottomPad: number
  /** Total canvas height — what the scroller's `scrollHeight` should come to. */
  canvasHeight: number
  /** Canvas px per row px. 1 below the cap. */
  scale: number
}

/** The rows to render for a scroll position, and the spacers that place them there. */
export function computeWindow(input: WindowInput): RowWindow {
  const { viewportHeight, rowHeight, count, overscan } = input
  const maxCanvas = input.maxCanvas ?? MAX_CANVAS_PX
  const contentHeight = count * rowHeight
  const canvasHeight = Math.min(contentHeight, maxCanvas)
  if (count === 0) return { start: 0, end: 0, topPad: 0, bottomPad: 0, canvasHeight: 0, scale: 1 }

  // How far the user has scrolled, as a fraction of the scrollable range, is the only
  // quantity that survives the cap: the same fraction of the row space is what they mean.
  const scrollable = Math.max(0, canvasHeight - viewportHeight)
  const scrollTop = Math.max(0, Math.min(input.scrollTop, scrollable))
  const scale = scrollable > 0 ? Math.max(0, contentHeight - viewportHeight) / scrollable : 1
  const contentTop = scrollTop * scale

  const firstVisible = Math.min(count - 1, Math.floor(contentTop / rowHeight))
  const visibleRows = Math.ceil(viewportHeight / rowHeight) + 1
  const start = Math.max(0, firstVisible - overscan)
  const end = Math.min(count, firstVisible + visibleRows + overscan)

  // Place the window so that `firstVisible` sits exactly where it would in an uncapped
  // layout relative to the viewport: at the scroll position, minus however far into the
  // row the viewport has already scrolled, minus the overscan rows above it.
  const withinRow = contentTop - firstVisible * rowHeight
  const topPad = Math.max(0, scrollTop - withinRow - (firstVisible - start) * rowHeight)
  const bottomPad = Math.max(0, canvasHeight - topPad - (end - start) * rowHeight)
  return { start, end, topPad, bottomPad, canvasHeight, scale }
}

@layer cascivo.component {
  .root {
    --_row-height: 3rem;
    display: flex;
    flex-direction: column;
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-surface);
    background-color: var(--cascivo-color-surface);
    overflow: hidden;
  }

  .root[data-density='compact'] {
    --_row-height: 2.25rem;
  }
  .root[data-density='normal'] {
    --_row-height: 3rem;
  }
  .root[data-density='relaxed'] {
    --_row-height: 3.75rem;
  }

  /* Toolbar */
  .toolbar {
    display: flex;
    align-items: flex-end;
    justify-content: space-between;
    gap: var(--cascivo-space-4);
    padding: var(--cascivo-space-3) var(--cascivo-space-4);
    border-block-end: 1px solid var(--cascivo-color-border);
  }

  .heading {
    display: flex;
    flex-direction: column;
    gap: var(--cascivo-space-1);
  }

  .title {
    font-size: var(--cascivo-text-base);
    font-weight: var(--cascivo-font-semibold);
    color: var(--cascivo-color-text);
  }

  .description {
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text-subtle);
  }

  .search {
    appearance: none;
    height: 2rem;
    min-inline-size: 14rem;
    padding-inline: var(--cascivo-space-3);
    font-family: var(--cascivo-font-sans);
    font-size: var(--cascivo-text-sm);
    color: var(--cascivo-color-text);
    background-color: var(--cascivo-color-surface);
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-field);
    outline: none;
    transition:
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      box-shadow var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover:not(:focus) {
      border-color: var(--cascivo-color-border-strong);
    }

    &:focus-visible {
      border-color: var(--cascivo-color-accent);
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--cascivo-color-accent) 20%, transparent);
    }
  }

  /* Batch bar */
  .batchBar {
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: var(--cascivo-space-4);
    padding: var(--cascivo-space-2) var(--cascivo-space-4);
    background-color: var(--cascivo-color-bg-subtle);
    border-block-end: 1px solid var(--cascivo-color-border);
  }

  .batchCount {
    font-size: var(--cascivo-text-sm);
    font-weight: var(--cascivo-font-medium);
    color: var(--cascivo-color-text);
  }

  .batchActions {
    display: flex;
    gap: var(--cascivo-space-2);
  }

  /* Table scroller */
  .scroller {
    overflow: auto;
    max-block-size: var(--cascivo-data-table-max-height, none);
    /* Reserve the gutter so a horizontally-scrollable table SAYS so. With an overlay
       scrollbar (the default on macOS and Android) columns past the fold simply vanish and
       it reads as "the table dropped my columns" — one adopter measured clientWidth 1052
       against scrollWidth 1360 before working out the rows were scrollable at all. */
    scrollbar-gutter: stable;

    /* Scrolling shadows: a soft edge appears only on the side there is more table to reach.
       `scrollbar-gutter` above says "this scrolls"; this says WHICH WAY and that content is
       cut off right now — the missing affordance behind a reported "the Created column was
       cut off at the right edge with no visible scrollbar" (2026-08-22 report item 17).

       Pure CSS, no JS and no scroll listener: the cover gradients scroll WITH the content
       (`local`) and hide the shadows when the table is flush against an edge, while the
       shadows are fixed to the box (`scroll`). A table that fits shows neither. */
    background-image:
      linear-gradient(to right, var(--cascivo-color-surface) 30%, transparent),
      linear-gradient(to left, var(--cascivo-color-surface) 30%, transparent),
      radial-gradient(farthest-side at 0 50%, var(--cascivo-color-border), transparent),
      radial-gradient(farthest-side at 100% 50%, var(--cascivo-color-border), transparent);
    background-position:
      0 0,
      100% 0,
      0 0,
      100% 0;
    background-repeat: no-repeat;
    background-size:
      2.5rem 100%,
      2.5rem 100%,
      0.875rem 100%,
      0.875rem 100%;
    background-attachment: local, local, scroll, scroll;
  }

  .scrollerVirtualized {
    overflow: auto;
    block-size: var(--cascivo-data-table-height, 400px);
    max-block-size: none;
  }

  .table {
    inline-size: 100%;
    border-collapse: collapse;
    table-layout: auto;
  }

  /* A fixed layout keeps column widths constant as the page changes, but it hands
     unsized columns only the leftover space with no content floor. With six of seven
     columns sized, the seventh collapsed to ~50px and wrapped one character per line.
     So it applies only when EVERY column declares a width — the one case where the
     stability guarantee costs nothing. Otherwise widths are preferred sizes under the
     auto algorithm, which still respects each column's content minimum. */
  .root[data-paginated='true'][data-fixed-layout='true'] .table {
    table-layout: fixed;
  }

  .table thead th {
    padding-block: var(--cascivo-space-2);
    padding-inline: var(--cascivo-data-table-cell-gap, var(--cascivo-space-4));
    text-align: start;
    font-weight: var(--cascivo-font-semibold);
    font-size: var(--cascivo-text-xs);
    text-transform: uppercase;
    letter-spacing: var(--cascivo-tracking-wide);
    color: var(--cascivo-color-text-subtle);
    background-color: var(--cascivo-color-bg-subtle);
    border-block-end: 1px solid var(--cascivo-color-border);
    white-space: nowrap;
  }

  .table thead th[data-align='end'] {
    text-align: end;
  }

  .table td {
    padding-block: 0;
    padding-inline: var(--cascivo-data-table-cell-gap, var(--cascivo-space-4));
    block-size: var(--_row-height);
    vertical-align: middle;
    border-block-end: 1px solid var(--cascivo-color-border);
    color: var(--cascivo-color-text);
  }

  /* Long unbroken tokens (commit hashes, branch names) wrap inside the cell instead of
     spilling past the padding into the adjacent column. Scoped to columns that declared a
     `width` — that is the identifier-shaped case this exists for. Applying it to a
     free-form column made a squeezed column wrap one character per line instead of
     pushing back on the layout. */
  /* A sized column must not be squeezed below its own content.
     `width` is a *preferred* size, but under `table-layout: fixed` — which kicks in once
     every column is sized — the browser will happily shrink one below its text, and
     `overflow-wrap: anywhere` then broke words mid-character ("Buildin" / "g"). The docs
     promised unsized columns never collapse below their content; sized ones now get the
     same floor.

     `break-word` rather than `anywhere` is load-bearing: `anywhere` participates in
     min-content sizing (making the floor one character wide, i.e. no floor at all), while
     `break-word` leaves min-content at the longest word and still wraps unbreakable
     strings. Pass `minWidth` to raise the floor above the content. */
  .table td[data-sized],
  .table th[data-sized] {
    overflow-wrap: break-word;
    min-inline-size: min-content;
  }

  .table td[data-align='end'] {
    text-align: end;
  }

  /* Spacer that pads partial pages to a constant height — no divider line. */
  .table tbody tr[data-filler-row] td {
    border-block-end: none;
  }

  /* Sticky header */
  .root[data-sticky-header='true'] .table thead th {
    position: sticky;
    inset-block-start: 0;
    z-index: var(--cascivo-z-raised, 10);
    background-color: var(--cascivo-color-surface);
  }

  /*
    A stuck header needs to say it is stuck. Until `scroll-state` there was no way to know:
    the header looks identical whether it is sitting in normal flow at the top of the table
    or floating over rows that have scrolled under it, so the first row reads as a header
    row. The horizontal affordance right below (`.scroller`'s local/scroll gradients) solved
    the same problem on the other axis and is the model for this one — CSS only, no listener.

    `container-type: scroll-state` on the scroller lets its descendants ask; `thead th` is a
    descendant, so this needs no wrapper and no DOM change. Progressive enhancement
    (Chrome 133+): elsewhere the header stays flat, exactly as it is today.
  */
  @supports (container-type: scroll-state) {
    /* `stuck` is asked OF the sticky element, so the header cell is the container — and a
       container cannot style itself, so the rule below paints the cell's own `::after`
       (verified in Chromium 141 against a real sticky `<th>`). */
    .root[data-sticky-header='true'] .table thead th {
      container-type: scroll-state;
    }

    @container scroll-state(stuck: top) {
      .root[data-sticky-header='true'] .table thead th::after {
        content: '';
        position: absolute;
        inset-inline: 0;
        inset-block-end: 0;
        block-size: 0.375rem;
        translate: 0 100%;
        pointer-events: none;
        background: linear-gradient(
          to bottom,
          color-mix(in srgb, var(--cascivo-color-text) 12%, transparent),
          transparent
        );
      }
    }
  }

  /* Zebra striping — `of .row` keeps expansion rows out of the count.

     NOT `--cascivo-color-bg-subtle`: every theme aliases that straight to
     `--cascivo-color-surface` (`themes/src/*.css`), so striping a table that sits on a
     surface — a table in a Card, which is the normal composition — painted the row the
     exact colour it already was. Measured ΔL of 0.0000 in all three themes; the prop was
     wired and did nothing, which is what the adopter reported as "no visible effect"
     (2026-08-08 report A).

     A translucent foreground overlay adapts instead of assuming: it darkens on light themes
     and lightens on dark ones, and it works on ANY background the table is placed on rather
     than only on the page background. */
  .root[data-zebra='true'] .table tbody tr:nth-child(even of .row) {
    background-color: var(
      --cascivo-table-zebra-bg,
      color-mix(in oklab, var(--cascivo-color-text) 5%, transparent)
    );
  }

  /* Control columns (expand button / checkbox) */
  .controlCol {
    inline-size: 3rem;
  }

  .controlCell {
    text-align: center;
    padding-inline: var(--cascivo-space-2);
  }

  /* Sort button */
  .sortButton {
    display: inline-flex;
    align-items: center;
    gap: var(--cascivo-space-1);
    background: none;
    border: none;
    padding: 0;
    font-family: inherit;
    font-size: inherit;
    font-weight: inherit;
    text-transform: inherit;
    letter-spacing: inherit;
    color: inherit;
    cursor: pointer;
    outline: none;

    &:focus-visible {
      text-decoration: underline;
    }

    &::after {
      content: '↕';
      font-size: 0.75em;
      opacity: 0.4;
    }

    &[data-state='ascending']::after {
      content: '↑';
      opacity: 0.9;
    }

    &[data-state='descending']::after {
      content: '↓';
      opacity: 0.9;
    }
  }

  /* Row */
  .row {
    content-visibility: auto;
    contain-intrinsic-size: auto var(--_row-height, 3rem);

    &[data-state='selected'] td {
      background-color: color-mix(in srgb, var(--cascivo-color-accent) 8%, transparent);
    }
  }

  /* Empty cell */
  .emptyCell {
    padding: var(--cascivo-space-8) var(--cascivo-space-4);
    text-align: center;
    color: var(--cascivo-color-text-muted);
  }

  /* Expansion row */
  .expansionRow {
    &[data-state='closed'] {
      display: none;
    }
  }

  .expansionGrid {
    overflow: hidden;
  }

  .expansionInner {
    padding: var(--cascivo-space-4);
  }

  /* Expand button */
  .expandButton {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 1.5rem;
    block-size: 1.5rem;
    background: none;
    border: none;
    cursor: pointer;
    color: var(--cascivo-color-text-muted);
    border-radius: var(--cascivo-radius-control);
    outline: none;

    &:focus-visible {
      box-shadow: 0 0 0 2px var(--cascivo-color-accent);
    }

    &:hover {
      color: var(--cascivo-color-text);
      background-color: var(--cascivo-color-bg-subtle);
    }
  }

  .chevron {
    display: block;
    inline-size: 0.75rem;
    block-size: 0.75rem;
    border-inline-end: 2px solid currentColor;
    border-block-end: 2px solid currentColor;
    transform: rotate(45deg);
    transition: transform var(--cascivo-duration-150) var(--cascivo-ease-out);
  }

  .expandButton[data-state='open'] .chevron {
    transform: rotate(-135deg);
  }

  /* Loading shimmer — compositor-safe (translate only) */
  .shimmer {
    display: block;
    block-size: 0.875rem;
    inline-size: 80%;
    position: relative;
    overflow: hidden;
    background-color: var(--cascivo-color-bg-subtle);
    border-radius: var(--cascivo-radius-indicator);

    &::after {
      content: '';
      position: absolute;
      inset: 0;
      translate: -100% 0;
      background: linear-gradient(90deg, transparent, var(--cascivo-color-surface), transparent);
      animation: global(cascivo-shimmer) var(--cascivo-duration-500, 500ms)
        var(--cascivo-ease-in-out, ease-in-out) infinite;
    }
  }

  /* Footer pagination */
  .footer {
    display: flex;
    align-items: center;
    justify-content: flex-end;
    gap: var(--cascivo-space-4);
    padding: var(--cascivo-space-3) var(--cascivo-space-4);
    border-block-start: 1px solid var(--cascivo-color-border);
    font-size: var(--cascivo-text-sm);
  }

  .pageSize {
    display: flex;
    align-items: center;
    gap: var(--cascivo-space-2);
    color: var(--cascivo-color-text-muted);

    select {
      appearance: none;
      height: 2rem;
      padding-inline: var(--cascivo-space-2);
      font-family: var(--cascivo-font-sans);
      font-size: var(--cascivo-text-sm);
      color: var(--cascivo-color-text);
      background-color: var(--cascivo-color-surface);
      border: 1px solid var(--cascivo-color-border);
      border-radius: var(--cascivo-radius-field);
      cursor: pointer;
      outline: none;

      &:focus-visible {
        border-color: var(--cascivo-color-accent);
        box-shadow: 0 0 0 3px color-mix(in srgb, var(--cascivo-color-accent) 20%, transparent);
      }
    }
  }

  .range {
    color: var(--cascivo-color-text-muted);
    white-space: nowrap;
  }

  .pageButtons {
    display: flex;
    gap: var(--cascivo-space-1);
  }

  .pageButton {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    inline-size: 2rem;
    block-size: 2rem;
    background: none;
    border: 1px solid var(--cascivo-color-border);
    border-radius: var(--cascivo-radius-control);
    cursor: pointer;
    color: var(--cascivo-color-text);
    font-size: var(--cascivo-text-base);
    outline: none;
    transition:
      background-color var(--cascivo-duration-150) var(--cascivo-ease-out),
      border-color var(--cascivo-duration-150) var(--cascivo-ease-out);

    &:hover:not(:disabled) {
      background-color: var(--cascivo-color-bg-subtle);
      border-color: var(--cascivo-color-border-strong);
    }

    &:focus-visible {
      border-color: var(--cascivo-color-accent);
      box-shadow: 0 0 0 3px color-mix(in srgb, var(--cascivo-color-accent) 20%, transparent);
    }

    &:disabled {
      /* Dim via a muted foreground, not opacity — opacity:0.4 on the glyph
         dropped the disabled arrow below 4.5:1 (WCAG color-contrast). */
      color: var(--cascivo-color-text-muted);
      cursor: not-allowed;
    }
  }

  /* Screen-reader only utility */
  .srOnly {
    position: absolute;
    inline-size: 1px;
    block-size: 1px;
    overflow: hidden;
    clip-path: inset(50%);
    white-space: nowrap;
  }
}
